clamp_prob <- function(
    p,
    eps = 1e-7
) {
  pmin(
    pmax(
      as.numeric(p),
      eps
    ),
    1 - eps
  )
}

fast_auc <- function(
    y,
    p
) {
  keep <- !is.na(y) &
    !is.na(p) &
    is.finite(p)

  y <- as.integer(
    y[keep]
  )
  p <- as.numeric(
    p[keep]
  )

  keep2 <- y %in% c(
    0L,
    1L
  )

  y <- y[keep2]
  p <- p[keep2]

  n1 <- as.double(
    sum(
      y == 1L
    )
  )
  n0 <- as.double(
    sum(
      y == 0L
    )
  )

  if (
    n1 == 0 ||
      n0 == 0
  ) {
    return(NA_real_)
  }

  r <- rank(
    p,
    ties.method = "average"
  )

  (
    sum(
      r[
        y == 1L
      ]
    ) -
      n1 *
        (
          n1 + 1
        ) /
        2
  ) /
    (
      n1 *
        n0
    )
}

fast_auprc <- function(
    y,
    p
) {
  keep <- !is.na(y) &
    !is.na(p) &
    is.finite(p)

  y <- as.integer(
    y[keep]
  )
  p <- as.numeric(
    p[keep]
  )

  keep2 <- y %in% c(
    0L,
    1L
  )

  y <- y[keep2]
  p <- p[keep2]

  n_pos <- sum(
    y == 1L
  )

  if (n_pos == 0L) {
    return(NA_real_)
  }

  ord <- order(
    p,
    decreasing = TRUE
  )
  yy <- y[ord]

  tp <- cumsum(
    yy == 1L
  )
  fp <- cumsum(
    yy == 0L
  )

  precision <- tp /
    (
      tp +
        fp
    )

  recall <- tp /
    n_pos

  recall_previous <- c(
    0,
    head(
      recall,
      -1L
    )
  )

  sum(
    precision *
      (
        recall -
          recall_previous
      ),
    na.rm = TRUE
  )
}

binary_calibration <- function(
    y,
    p
) {
  keep <- !is.na(y) &
    !is.na(p) &
    is.finite(p)

  y <- as.integer(
    y[keep]
  )
  p <- clamp_prob(
    p[keep]
  )

  if (
    length(
      unique(
        y
      )
    ) <
      2L
  ) {
    return(
      c(
        intercept = NA_real_,
        slope = NA_real_
      )
    )
  }

  lp <- qlogis(
    p
  )

  fit_i <- tryCatch(
    glm(
      y ~ 1,
      family = binomial(),
      offset = lp
    ),
    error = function(e) NULL
  )

  fit_s <- tryCatch(
    glm(
      y ~ lp,
      family = binomial()
    ),
    error = function(e) NULL
  )

  c(
    intercept =
      if (
        is.null(
          fit_i
        )
      ) {
        NA_real_
      } else {
        unname(
          coef(
            fit_i
          )[1L]
        )
      },
    slope =
      if (
        is.null(
          fit_s
        )
      ) {
        NA_real_
      } else {
        unname(
          coef(
            fit_s
          )["lp"]
        )
      }
  )
}

binary_metrics <- function(
    y,
    p
) {
  pp <- clamp_prob(
    p
  )
  cal <- binary_calibration(
    y,
    p
  )

  data.table(
    N = length(
      y
    ),
    events = sum(
      y == 1L
    ),
    prevalence = mean(
      y == 1L
    ),
    AUROC = fast_auc(
      y,
      p
    ),
    AUPRC = fast_auprc(
      y,
      p
    ),
    AUPRC_to_prevalence =
      fast_auprc(
        y,
        p
      ) /
        mean(
          y == 1L
        ),
    Brier = mean(
      (
        p -
          y
      )^2
    ),
    log_loss =
      -mean(
        y *
          log(
            pp
          ) +
          (
            1 -
              y
          ) *
            log(
              1 -
                pp
            )
      ),
    calibration_intercept =
      unname(
        cal[
          "intercept"
        ]
      ),
    calibration_slope =
      unname(
        cal[
          "slope"
        ]
      )
  )
}

pinball_loss <- function(
    y,
    q,
    alpha
) {
  e <- y - q

  mean(
    ifelse(
      e >= 0,
      alpha *
        e,
      (
        alpha -
          1
      ) *
        e
    ),
    na.rm = TRUE
  )
}

